-- FK 삭제·수정 규칙과 컬럼 IDENTITY (docs/lexorma-example-sync.md 2장)
--  1) TB_TBL_REL.DEL_RULE_CD · MDFCN_RULE_CD : FK 의 ON DELETE · ON UPDATE 규칙 (비면 NO ACTION). 기존 관계는 비어 있어 지금까지와 같다
--  2) TB_COL.AUTO_CRT_MTHD_CD : 컬럼 값 자동 생성 방법 (IDENTITY ALWAYS · BY_DEFAULT, 비면 없음). 기존 컬럼은 비어 있다
--  3) 예제 (데이터 사전 용어 → 물리 → 논리 → 매핑) 와 LEXORMA 예제의 실제 규칙 (FK 13개) · IDENTITY (TB_LOG.LOG_SN) — 비어 있을 때만 채운다
-- 이미 적용된 V0~V6 는 고치지 않는다.

alter table TB_TBL_REL add column DEL_RULE_CD varchar(20);
alter table TB_TBL_REL add column MDFCN_RULE_CD varchar(20);
alter table TB_COL add column AUTO_CRT_MTHD_CD varchar(20);

comment on column TB_TBL_REL.DEL_RULE_CD is '삭제 규칙 코드';
comment on column TB_TBL_REL.MDFCN_RULE_CD is '수정 규칙 코드';
comment on column TB_COL.AUTO_CRT_MTHD_CD is '자동 생성 방법 코드';

-- ---------- 예제 : 데이터 사전 (용어·용어 단어, 새 단어 없음). 같은 이름이 이미 있으면 넣지 않는다 ----------
insert into TB_STD_TRM(STD_TRM_SN, PRJ_SN, ENCT_CYCL, TRM_NM, TRM_EXPLN, TRM_ENG_ABBR_NM, PBADMS_STD_CD_NM, JRSDC_INST_NM, STD_DMN_SN, APRV_YN, REG_DT, MDFCN_DT, RGTR_ID, MDFR_ID) select nextval('SQ_STD_TRM'), 0, 1, '삭제_규칙_코드', 'FK 의 ON DELETE 규칙 : NO_ACTION · RESTRICT · CASCADE · SET_NULL · SET_DEFAULT (비면 NO ACTION).', 'DEL_RULE_CD', null, null, d.STD_DMN_SN, true, current_timestamp, current_timestamp, 'SYSTEM', 'SYSTEM' from TB_STD_DMN d where d.PRJ_SN = 0 and d.DMN_NM = '코드V20' and not exists (select 1 from TB_STD_TRM where PRJ_SN = 0 and TRM_NM = '삭제_규칙_코드');
insert into TB_STD_TRM_WORD(STD_TRM_WORD_SN, STD_TRM_SN, STD_WORD_SN, SORT_ORD, REG_DT, MDFCN_DT, RGTR_ID, MDFR_ID) select nextval('SQ_STD_TRM_WORD'), t.STD_TRM_SN, w.STD_WORD_SN, 1, current_timestamp, current_timestamp, 'SYSTEM', 'SYSTEM' from TB_STD_TRM t join TB_STD_WORD w on w.PRJ_SN = 0 and w.WORD_NM = '삭제' where t.PRJ_SN = 0 and t.TRM_NM = '삭제_규칙_코드' and not exists (select 1 from TB_STD_TRM_WORD x where x.STD_TRM_SN = t.STD_TRM_SN and x.SORT_ORD = 1);
insert into TB_STD_TRM_WORD(STD_TRM_WORD_SN, STD_TRM_SN, STD_WORD_SN, SORT_ORD, REG_DT, MDFCN_DT, RGTR_ID, MDFR_ID) select nextval('SQ_STD_TRM_WORD'), t.STD_TRM_SN, w.STD_WORD_SN, 2, current_timestamp, current_timestamp, 'SYSTEM', 'SYSTEM' from TB_STD_TRM t join TB_STD_WORD w on w.PRJ_SN = 0 and w.WORD_NM = '규칙' where t.PRJ_SN = 0 and t.TRM_NM = '삭제_규칙_코드' and not exists (select 1 from TB_STD_TRM_WORD x where x.STD_TRM_SN = t.STD_TRM_SN and x.SORT_ORD = 2);
insert into TB_STD_TRM_WORD(STD_TRM_WORD_SN, STD_TRM_SN, STD_WORD_SN, SORT_ORD, REG_DT, MDFCN_DT, RGTR_ID, MDFR_ID) select nextval('SQ_STD_TRM_WORD'), t.STD_TRM_SN, w.STD_WORD_SN, 3, current_timestamp, current_timestamp, 'SYSTEM', 'SYSTEM' from TB_STD_TRM t join TB_STD_WORD w on w.PRJ_SN = 0 and w.WORD_NM = '코드' where t.PRJ_SN = 0 and t.TRM_NM = '삭제_규칙_코드' and not exists (select 1 from TB_STD_TRM_WORD x where x.STD_TRM_SN = t.STD_TRM_SN and x.SORT_ORD = 3);
insert into TB_STD_TRM(STD_TRM_SN, PRJ_SN, ENCT_CYCL, TRM_NM, TRM_EXPLN, TRM_ENG_ABBR_NM, PBADMS_STD_CD_NM, JRSDC_INST_NM, STD_DMN_SN, APRV_YN, REG_DT, MDFCN_DT, RGTR_ID, MDFR_ID) select nextval('SQ_STD_TRM'), 0, 1, '수정_규칙_코드', 'FK 의 ON UPDATE 규칙 : NO_ACTION · RESTRICT · CASCADE · SET_NULL · SET_DEFAULT (비면 NO ACTION).', 'MDFCN_RULE_CD', null, null, d.STD_DMN_SN, true, current_timestamp, current_timestamp, 'SYSTEM', 'SYSTEM' from TB_STD_DMN d where d.PRJ_SN = 0 and d.DMN_NM = '코드V20' and not exists (select 1 from TB_STD_TRM where PRJ_SN = 0 and TRM_NM = '수정_규칙_코드');
insert into TB_STD_TRM_WORD(STD_TRM_WORD_SN, STD_TRM_SN, STD_WORD_SN, SORT_ORD, REG_DT, MDFCN_DT, RGTR_ID, MDFR_ID) select nextval('SQ_STD_TRM_WORD'), t.STD_TRM_SN, w.STD_WORD_SN, 1, current_timestamp, current_timestamp, 'SYSTEM', 'SYSTEM' from TB_STD_TRM t join TB_STD_WORD w on w.PRJ_SN = 0 and w.WORD_NM = '수정' where t.PRJ_SN = 0 and t.TRM_NM = '수정_규칙_코드' and not exists (select 1 from TB_STD_TRM_WORD x where x.STD_TRM_SN = t.STD_TRM_SN and x.SORT_ORD = 1);
insert into TB_STD_TRM_WORD(STD_TRM_WORD_SN, STD_TRM_SN, STD_WORD_SN, SORT_ORD, REG_DT, MDFCN_DT, RGTR_ID, MDFR_ID) select nextval('SQ_STD_TRM_WORD'), t.STD_TRM_SN, w.STD_WORD_SN, 2, current_timestamp, current_timestamp, 'SYSTEM', 'SYSTEM' from TB_STD_TRM t join TB_STD_WORD w on w.PRJ_SN = 0 and w.WORD_NM = '규칙' where t.PRJ_SN = 0 and t.TRM_NM = '수정_규칙_코드' and not exists (select 1 from TB_STD_TRM_WORD x where x.STD_TRM_SN = t.STD_TRM_SN and x.SORT_ORD = 2);
insert into TB_STD_TRM_WORD(STD_TRM_WORD_SN, STD_TRM_SN, STD_WORD_SN, SORT_ORD, REG_DT, MDFCN_DT, RGTR_ID, MDFR_ID) select nextval('SQ_STD_TRM_WORD'), t.STD_TRM_SN, w.STD_WORD_SN, 3, current_timestamp, current_timestamp, 'SYSTEM', 'SYSTEM' from TB_STD_TRM t join TB_STD_WORD w on w.PRJ_SN = 0 and w.WORD_NM = '코드' where t.PRJ_SN = 0 and t.TRM_NM = '수정_규칙_코드' and not exists (select 1 from TB_STD_TRM_WORD x where x.STD_TRM_SN = t.STD_TRM_SN and x.SORT_ORD = 3);
insert into TB_STD_TRM(STD_TRM_SN, PRJ_SN, ENCT_CYCL, TRM_NM, TRM_EXPLN, TRM_ENG_ABBR_NM, PBADMS_STD_CD_NM, JRSDC_INST_NM, STD_DMN_SN, APRV_YN, REG_DT, MDFCN_DT, RGTR_ID, MDFR_ID) select nextval('SQ_STD_TRM'), 0, 1, '자동_생성_방법_코드', '컬럼 값 자동 생성 방법(IDENTITY) : ALWAYS · BY_DEFAULT (비면 없음).', 'AUTO_CRT_MTHD_CD', null, null, d.STD_DMN_SN, true, current_timestamp, current_timestamp, 'SYSTEM', 'SYSTEM' from TB_STD_DMN d where d.PRJ_SN = 0 and d.DMN_NM = '코드V20' and not exists (select 1 from TB_STD_TRM where PRJ_SN = 0 and TRM_NM = '자동_생성_방법_코드');
insert into TB_STD_TRM_WORD(STD_TRM_WORD_SN, STD_TRM_SN, STD_WORD_SN, SORT_ORD, REG_DT, MDFCN_DT, RGTR_ID, MDFR_ID) select nextval('SQ_STD_TRM_WORD'), t.STD_TRM_SN, w.STD_WORD_SN, 1, current_timestamp, current_timestamp, 'SYSTEM', 'SYSTEM' from TB_STD_TRM t join TB_STD_WORD w on w.PRJ_SN = 0 and w.WORD_NM = '자동' where t.PRJ_SN = 0 and t.TRM_NM = '자동_생성_방법_코드' and not exists (select 1 from TB_STD_TRM_WORD x where x.STD_TRM_SN = t.STD_TRM_SN and x.SORT_ORD = 1);
insert into TB_STD_TRM_WORD(STD_TRM_WORD_SN, STD_TRM_SN, STD_WORD_SN, SORT_ORD, REG_DT, MDFCN_DT, RGTR_ID, MDFR_ID) select nextval('SQ_STD_TRM_WORD'), t.STD_TRM_SN, w.STD_WORD_SN, 2, current_timestamp, current_timestamp, 'SYSTEM', 'SYSTEM' from TB_STD_TRM t join TB_STD_WORD w on w.PRJ_SN = 0 and w.WORD_NM = '생성' where t.PRJ_SN = 0 and t.TRM_NM = '자동_생성_방법_코드' and not exists (select 1 from TB_STD_TRM_WORD x where x.STD_TRM_SN = t.STD_TRM_SN and x.SORT_ORD = 2);
insert into TB_STD_TRM_WORD(STD_TRM_WORD_SN, STD_TRM_SN, STD_WORD_SN, SORT_ORD, REG_DT, MDFCN_DT, RGTR_ID, MDFR_ID) select nextval('SQ_STD_TRM_WORD'), t.STD_TRM_SN, w.STD_WORD_SN, 3, current_timestamp, current_timestamp, 'SYSTEM', 'SYSTEM' from TB_STD_TRM t join TB_STD_WORD w on w.PRJ_SN = 0 and w.WORD_NM = '방법' where t.PRJ_SN = 0 and t.TRM_NM = '자동_생성_방법_코드' and not exists (select 1 from TB_STD_TRM_WORD x where x.STD_TRM_SN = t.STD_TRM_SN and x.SORT_ORD = 3);
insert into TB_STD_TRM_WORD(STD_TRM_WORD_SN, STD_TRM_SN, STD_WORD_SN, SORT_ORD, REG_DT, MDFCN_DT, RGTR_ID, MDFR_ID) select nextval('SQ_STD_TRM_WORD'), t.STD_TRM_SN, w.STD_WORD_SN, 4, current_timestamp, current_timestamp, 'SYSTEM', 'SYSTEM' from TB_STD_TRM t join TB_STD_WORD w on w.PRJ_SN = 0 and w.WORD_NM = '코드' where t.PRJ_SN = 0 and t.TRM_NM = '자동_생성_방법_코드' and not exists (select 1 from TB_STD_TRM_WORD x where x.STD_TRM_SN = t.STD_TRM_SN and x.SORT_ORD = 4);

-- ---------- 예제 : 물리 모델 (같은 이름이 이미 있으면 넣지 않는다) ----------
insert into TB_COL(COL_SN, PRJ_SN, TBL_SN, TBL_NM, COL_NM, COL_EXPLN, DATA_TYPE_NM, MAX_LEN, DATA_PRCSN, DCPT_LEN, NULL_ALWNC_YN, BSC_VL, SORT_ORD, MSTR_DATA_YN, RFRNC_TBL_NM, ESNTL_YN, SNSTV_INFO_YN, PK_YN, UNQ_YN, IDX_YN, ENCPT_YN, APRV_YN, STD_TRM_SN, REG_DT, MDFCN_DT, RGTR_ID, MDFR_ID) select nextval('SQ_COL'), 0, t.TBL_SN, 'TB_TBL_REL', 'DEL_RULE_CD', '삭제 규칙 코드', 'VARCHAR', 20, null, null, true, null, (select coalesce(max(c2.SORT_ORD), 0) + 1 from TB_COL c2 where c2.TBL_SN = t.TBL_SN), false, null, false, false, false, false, false, false, true, (select STD_TRM_SN from TB_STD_TRM where PRJ_SN = 0 and TRM_NM = '삭제_규칙_코드'), current_timestamp, current_timestamp, 'SYSTEM', 'SYSTEM' from TB_TBL t where t.PRJ_SN = 0 and t.TBL_NM = 'TB_TBL_REL' and not exists (select 1 from TB_COL c where c.TBL_SN = t.TBL_SN and c.COL_NM = 'DEL_RULE_CD');
insert into TB_COL(COL_SN, PRJ_SN, TBL_SN, TBL_NM, COL_NM, COL_EXPLN, DATA_TYPE_NM, MAX_LEN, DATA_PRCSN, DCPT_LEN, NULL_ALWNC_YN, BSC_VL, SORT_ORD, MSTR_DATA_YN, RFRNC_TBL_NM, ESNTL_YN, SNSTV_INFO_YN, PK_YN, UNQ_YN, IDX_YN, ENCPT_YN, APRV_YN, STD_TRM_SN, REG_DT, MDFCN_DT, RGTR_ID, MDFR_ID) select nextval('SQ_COL'), 0, t.TBL_SN, 'TB_TBL_REL', 'MDFCN_RULE_CD', '수정 규칙 코드', 'VARCHAR', 20, null, null, true, null, (select coalesce(max(c2.SORT_ORD), 0) + 1 from TB_COL c2 where c2.TBL_SN = t.TBL_SN), false, null, false, false, false, false, false, false, true, (select STD_TRM_SN from TB_STD_TRM where PRJ_SN = 0 and TRM_NM = '수정_규칙_코드'), current_timestamp, current_timestamp, 'SYSTEM', 'SYSTEM' from TB_TBL t where t.PRJ_SN = 0 and t.TBL_NM = 'TB_TBL_REL' and not exists (select 1 from TB_COL c where c.TBL_SN = t.TBL_SN and c.COL_NM = 'MDFCN_RULE_CD');
insert into TB_COL(COL_SN, PRJ_SN, TBL_SN, TBL_NM, COL_NM, COL_EXPLN, DATA_TYPE_NM, MAX_LEN, DATA_PRCSN, DCPT_LEN, NULL_ALWNC_YN, BSC_VL, SORT_ORD, MSTR_DATA_YN, RFRNC_TBL_NM, ESNTL_YN, SNSTV_INFO_YN, PK_YN, UNQ_YN, IDX_YN, ENCPT_YN, APRV_YN, STD_TRM_SN, REG_DT, MDFCN_DT, RGTR_ID, MDFR_ID) select nextval('SQ_COL'), 0, t.TBL_SN, 'TB_COL', 'AUTO_CRT_MTHD_CD', '자동 생성 방법 코드', 'VARCHAR', 20, null, null, true, null, (select coalesce(max(c2.SORT_ORD), 0) + 1 from TB_COL c2 where c2.TBL_SN = t.TBL_SN), false, null, false, false, false, false, false, false, true, (select STD_TRM_SN from TB_STD_TRM where PRJ_SN = 0 and TRM_NM = '자동_생성_방법_코드'), current_timestamp, current_timestamp, 'SYSTEM', 'SYSTEM' from TB_TBL t where t.PRJ_SN = 0 and t.TBL_NM = 'TB_COL' and not exists (select 1 from TB_COL c where c.TBL_SN = t.TBL_SN and c.COL_NM = 'AUTO_CRT_MTHD_CD');

-- ---------- 예제 : 논리 모델 (속성). LEXORMA 논리 모델이 있을 때만 ----------
insert into TB_LGCL_ATRB(LGCL_ATRB_SN, LGCL_ENTT_SN, ATRB_NM, ATRB_EXPLN, DATA_TYPE_NM, ESNTL_YN, SORT_ORD, STD_TRM_SN, REG_DT, MDFCN_DT, RGTR_ID, MDFR_ID) select nextval('SQ_LGCL_ATRB'), e.LGCL_ENTT_SN, '삭제 규칙 코드', null, null, false, (select coalesce(max(a2.SORT_ORD), 0) + 1 from TB_LGCL_ATRB a2 where a2.LGCL_ENTT_SN = e.LGCL_ENTT_SN), (select STD_TRM_SN from TB_STD_TRM where PRJ_SN = 0 and TRM_NM = '삭제_규칙_코드'), current_timestamp, current_timestamp, 'SYSTEM', 'SYSTEM' from TB_LGCL_ENTT e where e.LGCL_MDL_SN = (select LGCL_MDL_SN from TB_LGCL_MDL where PRJ_SN = 0 and MDL_NM = 'LEXORMA') and e.ENTT_NM = '테이블 관계' and not exists (select 1 from TB_LGCL_ATRB a where a.LGCL_ENTT_SN = e.LGCL_ENTT_SN and a.ATRB_NM = '삭제 규칙 코드');
insert into TB_LGCL_ATRB(LGCL_ATRB_SN, LGCL_ENTT_SN, ATRB_NM, ATRB_EXPLN, DATA_TYPE_NM, ESNTL_YN, SORT_ORD, STD_TRM_SN, REG_DT, MDFCN_DT, RGTR_ID, MDFR_ID) select nextval('SQ_LGCL_ATRB'), e.LGCL_ENTT_SN, '수정 규칙 코드', null, null, false, (select coalesce(max(a2.SORT_ORD), 0) + 1 from TB_LGCL_ATRB a2 where a2.LGCL_ENTT_SN = e.LGCL_ENTT_SN), (select STD_TRM_SN from TB_STD_TRM where PRJ_SN = 0 and TRM_NM = '수정_규칙_코드'), current_timestamp, current_timestamp, 'SYSTEM', 'SYSTEM' from TB_LGCL_ENTT e where e.LGCL_MDL_SN = (select LGCL_MDL_SN from TB_LGCL_MDL where PRJ_SN = 0 and MDL_NM = 'LEXORMA') and e.ENTT_NM = '테이블 관계' and not exists (select 1 from TB_LGCL_ATRB a where a.LGCL_ENTT_SN = e.LGCL_ENTT_SN and a.ATRB_NM = '수정 규칙 코드');
insert into TB_LGCL_ATRB(LGCL_ATRB_SN, LGCL_ENTT_SN, ATRB_NM, ATRB_EXPLN, DATA_TYPE_NM, ESNTL_YN, SORT_ORD, STD_TRM_SN, REG_DT, MDFCN_DT, RGTR_ID, MDFR_ID) select nextval('SQ_LGCL_ATRB'), e.LGCL_ENTT_SN, '자동 생성 방법 코드', null, null, false, (select coalesce(max(a2.SORT_ORD), 0) + 1 from TB_LGCL_ATRB a2 where a2.LGCL_ENTT_SN = e.LGCL_ENTT_SN), (select STD_TRM_SN from TB_STD_TRM where PRJ_SN = 0 and TRM_NM = '자동_생성_방법_코드'), current_timestamp, current_timestamp, 'SYSTEM', 'SYSTEM' from TB_LGCL_ENTT e where e.LGCL_MDL_SN = (select LGCL_MDL_SN from TB_LGCL_MDL where PRJ_SN = 0 and MDL_NM = 'LEXORMA') and e.ENTT_NM = '컬럼' and not exists (select 1 from TB_LGCL_ATRB a where a.LGCL_ENTT_SN = e.LGCL_ENTT_SN and a.ATRB_NM = '자동 생성 방법 코드');

-- ---------- 예제 : 논리 ↔ 물리 매핑 (V2~V5 와 같은 규칙 : 새 속성만 이어진다) ----------
insert into TB_ATRB_COL_MPNG(ATRB_COL_MPNG_SN, ENTT_TBL_MPNG_SN, LGCL_ATRB_SN, COL_SN, REG_DT, MDFCN_DT, RGTR_ID, MDFR_ID)
select nextval('SQ_ATRB_COL_MPNG'), mp.ENTT_TBL_MPNG_SN, a.LGCL_ATRB_SN, c.COL_SN, current_timestamp, current_timestamp, 'SYSTEM', 'SYSTEM'
from TB_ENTT_TBL_MPNG mp
join TB_LGCL_ENTT e on e.LGCL_ENTT_SN = mp.LGCL_ENTT_SN
join TB_LGCL_MDL m on m.LGCL_MDL_SN = e.LGCL_MDL_SN and m.PRJ_SN = 0 and m.MDL_NM = 'LEXORMA'
join TB_TBL t on t.TBL_SN = mp.TBL_SN and t.TBL_KORN_NM = e.ENTT_NM
join TB_LGCL_ATRB a on a.LGCL_ENTT_SN = e.LGCL_ENTT_SN
join TB_COL c on c.TBL_SN = t.TBL_SN and c.STD_TRM_SN = a.STD_TRM_SN
where mp.PRJ_SN = 0
  and (select count(*) from TB_LGCL_ATRB a2 where a2.LGCL_ENTT_SN = e.LGCL_ENTT_SN and a2.STD_TRM_SN = a.STD_TRM_SN) = 1
  and (select count(*) from TB_COL c2 where c2.TBL_SN = t.TBL_SN and c2.STD_TRM_SN = a.STD_TRM_SN) = 1
  and not exists (select 1 from TB_ATRB_COL_MPNG x where x.LGCL_ATRB_SN = a.LGCL_ATRB_SN)
  and not exists (select 1 from TB_ATRB_COL_MPNG x where x.COL_SN = c.COL_SN);

-- ---------- LEXORMA 예제의 실제 규칙 · IDENTITY (비어 있을 때만) ----------
update TB_TBL_REL set DEL_RULE_CD = 'CASCADE' where PRJ_SN = 0 and upper(REL_NM) = 'FK_IDX_CHG_DMND_01' and REL_TYPE_CD = 'FK' and DEL_RULE_CD is null;
update TB_TBL_REL set DEL_RULE_CD = 'SET_NULL' where PRJ_SN = 0 and upper(REL_NM) = 'FK_SRC_SCHM_MPNG_01' and REL_TYPE_CD = 'FK' and DEL_RULE_CD is null;
update TB_TBL_REL set DEL_RULE_CD = 'SET_NULL' where PRJ_SN = 0 and upper(REL_NM) = 'FK_SRC_TBL_MPNG_01' and REL_TYPE_CD = 'FK' and DEL_RULE_CD is null;
update TB_TBL_REL set DEL_RULE_CD = 'CASCADE' where PRJ_SN = 0 and upper(REL_NM) = 'FK_TBL_CNSTRT_01' and REL_TYPE_CD = 'FK' and DEL_RULE_CD is null;
update TB_TBL_REL set DEL_RULE_CD = 'CASCADE' where PRJ_SN = 0 and upper(REL_NM) = 'FK_TBL_CNSTRT_COL_01' and REL_TYPE_CD = 'FK' and DEL_RULE_CD is null;
update TB_TBL_REL set DEL_RULE_CD = 'CASCADE' where PRJ_SN = 0 and upper(REL_NM) = 'FK_TBL_IDX_01' and REL_TYPE_CD = 'FK' and DEL_RULE_CD is null;
update TB_TBL_REL set DEL_RULE_CD = 'CASCADE' where PRJ_SN = 0 and upper(REL_NM) = 'FK_TBL_IDX_COL_01' and REL_TYPE_CD = 'FK' and DEL_RULE_CD is null;
update TB_TBL_REL set DEL_RULE_CD = 'CASCADE' where PRJ_SN = 0 and upper(REL_NM) = 'FK_TBL_REL_01' and REL_TYPE_CD = 'FK' and DEL_RULE_CD is null;
update TB_TBL_REL set DEL_RULE_CD = 'CASCADE' where PRJ_SN = 0 and upper(REL_NM) = 'FK_TBL_REL_02' and REL_TYPE_CD = 'FK' and DEL_RULE_CD is null;
update TB_TBL_REL set DEL_RULE_CD = 'CASCADE' where PRJ_SN = 0 and upper(REL_NM) = 'FK_TBL_REL_COL_01' and REL_TYPE_CD = 'FK' and DEL_RULE_CD is null;
update TB_TBL_REL set DEL_RULE_CD = 'CASCADE' where PRJ_SN = 0 and upper(REL_NM) = 'FK_VIEW_CHG_DMND_01' and REL_TYPE_CD = 'FK' and DEL_RULE_CD is null;
update TB_TBL_REL set DEL_RULE_CD = 'CASCADE' where PRJ_SN = 0 and upper(REL_NM) = 'FK_VIEW_COL_01' and REL_TYPE_CD = 'FK' and DEL_RULE_CD is null;
update TB_TBL_REL set DEL_RULE_CD = 'CASCADE' where PRJ_SN = 0 and upper(REL_NM) = 'FK_VIEW_RFRNC_01' and REL_TYPE_CD = 'FK' and DEL_RULE_CD is null;
update TB_COL set AUTO_CRT_MTHD_CD = 'BY_DEFAULT' where PRJ_SN = 0 and TBL_NM = 'TB_LOG' and COL_NM = 'LOG_SN' and AUTO_CRT_MTHD_CD is null;
